import{_ as a,o,c as n,a2 as t}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/es/planejadores-detalhe.png",r="/pro-agent-hub-installer/capturas/es/planejadores-execucao.png",h=JSON.parse('{"title":"Planificadores","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/planejadores.md","filePath":"es/interface/planejadores.md","lastUpdated":1787856241000}'),l={name:"es/interface/planejadores.md"};function i(d,e,c,u,p,m){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="planificadores" tabindex="-1">Planificadores <a class="header-anchor" href="#planificadores" aria-label="Permalink to &quot;Planificadores&quot;">​</a></h1><p>Un <strong>workflow</strong> conoce el camino de antemano; tú dibujaste cada paso. Un <strong>planificador</strong> no: le das el objetivo y él descubre el camino, un paso a la vez.</p><p>El ciclo es siempre el mismo — <strong>planificar → actuar → observar → evaluar → replanificar</strong> — y se repite hasta cumplir el criterio de éxito o chocar con un límite.</p><p>Usa un planificador cuando los pasos dependen de lo que se encuentre por el camino. Cuando ya conoces la secuencia, un workflow es más barato, más rápido y más previsible.</p><h2 id="pestana-general" tabindex="-1">Pestaña General <a class="header-anchor" href="#pestana-general" aria-label="Permalink to &quot;Pestaña General&quot;">​</a></h2><p><img src="'+s+'" alt="planejadores-detalhe"></p><p><strong>Objetivo</strong> es lo que se quiere alcanzar. Queda guardado como valor por defecto y puede sustituirse en cada disparo — desde la pantalla de ejecución, desde un workflow o por la API.</p><p><strong>Criterio de éxito</strong> es el texto que el modelo evalúa al final de cada vuelta para decidir si ya llegó. Sin él, el planificador solo para en los límites, y gastará todas las iteraciones que pueda. Escribe algo verificable: &quot;el archivo se grabó y la respuesta contiene el total calculado&quot; funciona; &quot;resolverlo bien&quot; no.</p><p><strong>Modelo</strong> es quien planifica y evalúa — no quien ejecuta. Vale más invertir en un buen modelo aquí que en los ejecutores: un plan malo desperdicia todas las vueltas siguientes.</p><p><strong>Agente base</strong> (opcional) es quien hace las acciones directas. Al definir uno, el planificador hereda los MCP, conocimientos y herramientas que ese agente ya tiene. Sin él, las acciones directas usan un agente efímero, sin nada vinculado.</p><h3 id="ejecutores" tabindex="-1">Ejecutores <a class="header-anchor" href="#ejecutores" aria-label="Permalink to &quot;Ejecutores&quot;">​</a></h3><p>Todavía en la pestaña General: los agentes y equipos que el planificador puede accionar. <strong>Esta lista es lo que el modelo ve al montar el plan</strong> — solo puede delegar un paso en quien esté aquí.</p><p>Cada vínculo lleva una descripción de lo que hace ese ejecutor. Escríbela pensando en quien lee: quien elige es el modelo, a partir de ese texto.</p><h3 id="limites" tabindex="-1">Límites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Límites&quot;">​</a></h3><p>Cierran la pestaña General. Son cuatro topes, todos comprobados <strong>entre pasos</strong> — nunca en medio de uno:</p><table tabindex="0"><thead><tr><th>Límite</th><th>Por defecto</th><th>Para qué sirve</th></tr></thead><tbody><tr><td>Iteraciones</td><td>15</td><td>Cuántas vueltas del ciclo.</td></tr><tr><td>Pasos</td><td>50</td><td>Cuántas acciones en total, sumando todas las vueltas.</td></tr><tr><td>Tokens</td><td>—</td><td>Presupuesto de tokens de la ejecución. Sin valor, sin tope.</td></tr><tr><td>Tiempo</td><td>900 s</td><td>Duración máxima.</td></tr></tbody></table><p>Estos límites no son un detalle de configuración: un planificador es un bucle guiado por un modelo, y el modelo puede no converger. Son ellos los que garantizan que la ejecución termina.</p><h2 id="pestana-herramientas" tabindex="-1">Pestaña Herramientas <a class="header-anchor" href="#pestana-herramientas" aria-label="Permalink to &quot;Pestaña Herramientas&quot;">​</a></h2><p>Qué operaciones internas puede llamar el bucle, y qué conexiones de base de datos puede tocar.</p><div class="warning custom-block"><p class="custom-block-title">Sin fuente de datos liberada, las funciones de base se rechazan</p><p><code>db_query</code>, <code>db_insert</code>, <code>db_update</code>, <code>db_delete</code> y <code>db_upsert</code> se bloquean <strong>antes de ejecutar</strong> cuando no hay ninguna conexión liberada. Es deliberado: sin una lista, el modelo tendría que adivinar el ID de la conexión, y acertar sería acceso a una base que el planificador no debería tocar.</p></div><p>La lista de herramientas disponibles está en <a href="/pro-agent-hub-installer/es/funcoes/planejador">Planificador</a>.</p><h2 id="pestanas-ejecutar-y-ejecuciones" tabindex="-1">Pestañas Ejecutar y Ejecuciones <a class="header-anchor" href="#pestanas-ejecutar-y-ejecuciones" aria-label="Permalink to &quot;Pestañas Ejecutar y Ejecuciones&quot;">​</a></h2><p><img src="'+r+'" alt="planejadores-execucao"></p><p>En <strong>Ejecutar</strong> disparas el planificador, opcionalmente cambiando el objetivo. La pantalla acompaña en vivo: el plan montado, cada paso con el ejecutor elegido, lo que se observó y la evaluación de la vuelta. Todo queda guardado, y la pestaña <strong>Ejecuciones</strong> conserva el historial — se puede reabrir una ejecución antigua y leer el razonamiento entero.</p><p>La ejecución termina como <strong>concluida</strong>, <strong>fallida</strong>, <strong>cancelada</strong> o por <strong>límite alcanzado</strong> — y, en este último caso, qué límite. Si un planificador vive chocando con <code>max_iterations</code>, el problema casi nunca es el tope: es el criterio de éxito o la descripción de los ejecutores.</p>',25)])])}const b=a(l,[["render",i]]);export{h as __pageData,b as default};
